    """
        Convert the value of a given currency to another currency type
        :param amount: float, The value of a given currency
        :param from_currency: string, source currency type
        :param to_currency: string, target currency type
        :return: float, value converted to another currency type
        """
    if from_currency == 'USD':
        converted_amount = amount
    elif from_currency in self.rates:
        converted_amount = amount / self.rates[from_currency]
    else:
        raise ValueError(f'{from_currency} is not a supported currency')
    if to_currency == 'USD':
        return converted_amount
    elif to_currency in self.rates:
        return converted_amount * self.rates[to_currency]
    else:
        raise ValueError(f'{to_currency} is not a supported currency')

